import{d as c,C as t,o as u,c as m,j as a,a as s,E as i,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第二十四章","description":"以企跨与四个自反观过度标举，辨余食赘形所喻的加作。","frontmatter":{"title":"道德经第二十四章","description":"以企跨与四个自反观过度标举，辨余食赘形所喻的加作。","category":"guide","aliases":["道德经第二十四章","老子第二十四章","dao de jing chapter 24"],"source":["王弼《道德真经注》卷二"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-24.md","filePath":"daoism/dao-de-jing/chapter-24.md","lastUpdated":1794189804000}'),g={name:"daoism/dao-de-jing/chapter-24.md"},y=c({...g,setup(x){const n=[{id:"tiptoes-and-overstriding",label:"企者不立，跨者不行",showLabel:!0,sentences:[[{text:"企",glossary:"qi"},"者不立，",{text:"跨",glossary:"kua"},"者不行；"]],note:["【白话】踮起脚跟求高，便站不稳；过分跨大步子求快，反而不能顺畅行走。这先用站立与行走说明过度用力可能损害安定。","【王弼注择要】「物尚进则失安，故曰企者不立。」王弼从一味求进而失安解释第一句；本页再依并列句理解跨的譬喻。","【读法】批评对象是刻意超过适宜尺度的强作，不是实际行走姿态本身，更不以站立、行走能力衡量人的价值。"]},{id:"four-self-assertions",label:"自见者不明，自是者不彰",showLabel:!0,sentences:[["自",{text:"见",glossary:"xian"},"者不明，",{text:"自是",glossary:"zishi"},"者不",{text:"彰",glossary:"zhang"},"；"],[{text:"自伐",glossary:"zifa"},"者无功，",{text:"自矜",glossary:"zijin"},"者不",{text:"长",glossary:"chang"},"。"]],note:["【白话】自我显露的人反不能明，自以为是的人反不能彰显；自夸功劳的人反不能成其功，自高自大的人反不能使德增长。","【王弼注择要】本处录文未给四句各附专注；第二十二章相应注文说「不自矜则其德长也」。两章对读，可见本章从相反方向说同一组自我标举之失。","【读法】见读 xiàn，长依本页与前章相同取径读 zhǎng。自伐针对夸功，不把它解作所有成果陈述；自是针对把自己当作唯一尺度。"]},{id:"surplus-and-accretion",label:"其在道也，曰余食赘形",showLabel:!0,sentences:[["其在道也，曰",{text:"余食",glossary:"yushi"},{text:"赘形",glossary:"zhuixing"},"。"],["物或",{text:"恶",glossary:"wu"},"之，故有道者不",{text:"处",glossary:"chu"},"。"]],note:["【白话】从道来看，这些就叫多余的食物和赘加的形体；人们或万物也可能厌弃它，所以有道的人不安处其中。","【王弼注择要】「本虽有功，而自伐之，故更为疣赘者也。」王弼将自夸比作功成之后又加出的累赘，说明问题不必在原有之功，而在后加的自伐。","【读法】本站赘形与录文赘行有异。这里借古代譬喻说明行为的多余加作，不借身体特征贬低他人；恶读 wù，处读 chǔ，取居处、安处义。"]}],r=[{id:"qi",term:"企",sense:1},{id:"kua",term:"跨",sense:1},{id:"xian",term:"见",sense:1,pinyin:"xiàn"},{id:"zishi",term:"自是",sense:1},{id:"zhang",term:"彰",sense:1},{id:"zifa",term:"自伐",sense:1},{id:"zijin",term:"自矜",sense:1},{id:"chang",term:"长",sense:2,pinyin:"zhǎng"},{id:"yushi",term:"余食",sense:1},{id:"zhuixing",term:"赘形",sense:1},{id:"wu",term:"恶",sense:1,pinyin:"wù"},{id:"chu",term:"处",sense:1}];return(b,e)=>{const o=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),m("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第二十四章",tabindex:"-1"},[s("道德经第二十四章 "),a("a",{class:"header-anchor",href:"#道德经第二十四章","aria-label":'Permalink to "道德经第二十四章"'},"​")],-1)),i(o,{title:"过分抬高自己，为什么反而站不稳",summary:"企与跨先写超出安定步态的强作，再以四个自指出自我标举之失；余食赘形的比喻，将有道者不处落在不依附多余加作。",points:[{label:"先读",text:"企与跨的身体譬喻怎样转到自见、自是、自伐、自矜。"},{label:"再辨",text:"与第二十二章逐句对读，辨同一组语词的正反说法。"},{label:"后看",text:"余食赘形批评额外加作，不以身体差异评价任何人的价值。"}],hint:"正文沿用赘形，所据录文作赘行；字形差异与王弼解释一并见篇末。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),i(l,{sections:n,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),i(d,{lines:[{text:"企者不立，跨者不行；",tone:"求进与失安",guide:"先看企、跨怎样影响原本的站立与行走，再转到后文的自我标举。"},{text:"自伐者无功，自矜者不长。",tone:"功与后加之物",guide:"有功之后自夸，不一定增加功的价值，反会遮住它。长字本页依王注取德增长义。"},{text:"物或恶之，故有道者不处。",tone:"不安处于此",guide:"将不处落实为减少多余加作，不把它读成禁止行动或交流。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(h,{items:r}),e[4]||(e[4]=p('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-企跨为什么能引出自见、自是" tabindex="-1">象：企跨为什么能引出自见、自是？ <a class="header-anchor" href="#象-企跨为什么能引出自见、自是" aria-label="Permalink to &quot;象：企跨为什么能引出自见、自是？&quot;">​</a></h3><p>企跨把求高、求快写成可感的动作，自见、自是等则把同一种过度伸张转到判断与功名。它们共同展示：一味把自身往前推，可能损伤原本想成就的事情。</p><h3 id="理-已有功劳-为什么自伐又会成为问题" tabindex="-1">理：已有功劳，为什么自伐又会成为问题？ <a class="header-anchor" href="#理-已有功劳-为什么自伐又会成为问题" aria-label="Permalink to &quot;理：已有功劳，为什么自伐又会成为问题？&quot;">​</a></h3><p>王弼明确承认本虽有功，再指出夸功形成附加的累赘。批评没有抹去实际成果，而是追问成果之后的占有、标举是否妨碍协作与继续生长。</p><h3 id="用-怎样区分清楚表达与自我显耀" tabindex="-1">用：怎样区分清楚表达与自我显耀？ <a class="header-anchor" href="#用-怎样区分清楚表达与自我显耀" aria-label="Permalink to &quot;用：怎样区分清楚表达与自我显耀？&quot;">​</a></h3><p>可以看表达是否帮助别人判断事实、作出决定，以及是否容得下遗漏与修正。说明自己的贡献、提出必要异议都可以清楚；把全部功劳归己、以身份代替理由，则接近本章所反省的自。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>检查额外动作是否有用。</strong> 完成一件事之后，可以问每一次汇报、包装与表态究竟增加了什么。必要的沟通应保留，只为抬高自身而增加的动作则可减少。</p><p><strong>让步幅符合承载。</strong> 制定目标时看实际资源与恢复能力，避免为了显得领先而不断加码。企跨的比喻提供尺度上的提醒，不否定在合适条件下努力进取。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我现在增加的一项动作，是事情需要，还是害怕自己显得不够突出？删去它，会损失真实价值吗？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>本站保留「余食赘形」；HFL 录文作「餘食贅行」。王弼该处用盛馔之余与疣赘说明多余，本页不将形、行差异隐去。</li><li>四个自与第二十二章对读，古注跨章引用已注明位置；不伪造本章每句都有独立注文。</li><li>恶取厌恶义读 wù，处取安处义读 chǔ；长沿本页所循德增长义读 zhǎng。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_002.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷二 HFL 本电子录文，003a–003b</a>。</p>',15))])}}});export{_ as __pageData,y as default};
